import createClient from 'openapi-fetch'

import { env } from '@/env'

import type { paths } from './schema'

// The typed API client. `paths` comes from schema.d.ts, generated by `bun run api:types`
// from __SERVER_DIR__/openapi.json; a request or response that drifts from the contract is a
// type error here, not a runtime surprise. `fetch` is resolved per call rather than
// captured at import time, so tests can stub `globalThis.fetch`.
//
// Only feature/*/server/ files import this module (lint enforces it). A loader that acts
// for the signed-in user builds a per-request client with that user's headers:
//   const api = createApi({ cookie: (await cookies()).toString() })
export function createApi(headers?: HeadersInit) {
  return createClient<paths>({
    baseUrl: env.API_URL,
    headers,
    fetch: (input) => globalThis.fetch(input),
  })
}

export const api = createApi()
